/**
 * API contract drift-check (generated by openapi-typescript).
 *
 * Statically links the HAND-WRITTEN UI types (camelCase, consumer-friendly)
 * to the GENERATED wire schema (snake_case, from backend Pydantic models).
 *
 * WHY THIS EXISTS: the Pydantic models in `backend/app/**` are the source of
 * truth for the wire contract. Hand-written UI types drift silently when the
 * backend renames/moves a field. This module is the compile-time tripwire: any
 * referenced generated field that no longer exists fails `tsc --noEmit`.
 *
 * USAGE: reference the generated wire types you actually consume under each
 * hand-written type. When the backend changes, `npm run typegen` regenerates
 * `api.ts` and this file stops compiling until the UI type is updated — in ONE
 * place, instead of silently mismatching across 23 files.
 *
 * NOTE: field names intentionally differ (snake_case wire vs camelCase UI).
 * This module checks STRUCTURE/EXISTENCE, not name equality — the UI mapping
 * lives in `src/api/*.ts` (see the standardized envelope unwrapping).
 */

import type { components } from './__generated__/api';

type Schemas = components['schemas'];

// ── Professional Mode ──
// UI: MorningBriefResponse (types/professional.ts) must cover the generated wire shape.
export type _WireMorningBrief = Schemas['MorningBriefResponse'];
export type _WireScreenSection = Schemas['ScreenSection'];
export type _WireTickerBrief = Schemas['TickerBrief'];
export type _WirePositionSizeResponse = Schemas['PositionSizeResponse'];
export type _WireAlertPreferences = Schemas['AlertPreferences'];

// ── Market / Sector ──
export type _WireMarketRegime = Schemas['MarketRegimeResponse'];
export type _WireSectorRotation = Schemas['SectorRotationResponse'];
export type _WireSectorDetail = Schemas['SectorDetail'];

// ── Ticker Analysis ──
export type _WireTickerRequest = Schemas['TickerAnalysisRequest'];
export type _WireScoredTicker = Schemas['ScoredTickerResponse'];
export type _WireEducation = Schemas['EducationResponse'];
export type _WireVerdict = Schemas['SimplifiedVerdictResponse'];
export type _WireWatchlist = Schemas['WatchlistAnalyzeResponse'];
export type _WireWatchlistItem = Schemas['WatchlistItemResponse'];

// ── Screener ──
export type _WireTVScreen = Schemas['TVScreenResponse'];

// ── Backtest / Risk ──
export type _WireBacktestRun = Schemas['BacktestRequest'];
export type _WireRiskKelly = Schemas['RiskKellyRequest'];
export type _WireRiskPositionSize = Schemas['RiskPositionSizeRequest'];

// ── Envelope (uniform across endpoints) ──
export type _WireApiResponse<T> = Schemas['ApiResponse'] & { data?: T };
